import { Effect, Layer, ServiceMap } from "effect"

export interface SignedEnvelope {
  readonly body: string
  readonly signature: string
  readonly nonce: string
  readonly issuedAt: number
}

export class EnvelopeSigner extends ServiceMap.Service<
  EnvelopeSigner,
  {
    readonly sign: (payload: unknown) => Effect.Effect<SignedEnvelope>
  }
>()("webhooks/EnvelopeSigner") {}

export const makeEnvelopeSignerLayer = (secretBase64: string) =>
  Layer.effect(
    EnvelopeSigner,
    Effect.gen(function*() {
      const crypto = yield* Effect.promise(() => import("node:crypto"))
      const key = crypto.createSecretKey(Buffer.from(secretBase64, "base64"))

      return {
        sign: (payload: unknown) =>
          Effect.gen(function*() {
            const nonce = crypto.randomUUID()
            const issuedAt = Date.now()
            const body = JSON.stringify({ payload, nonce, issuedAt })
            const signature = crypto
              .createHmac("sha256", key)
              .update(body)
              .digest("hex")

            return { body, signature, nonce, issuedAt }
          })
      }
    })
  )
